import type { ContentTree } from "./tree.ts";
import type { ValidationResult } from "./validate.ts";

const pct = (n: number, d: number) => (d === 0 ? "0%" : `${Math.round((n / d) * 1000) / 10}%`);
const esc = (s: string) => s.replaceAll("|", "\\|");

/** Render docs/coverage/*.md: a summary plus one file per section. Generated — do not edit. */
export function renderCoverage(result: ValidationResult, tree: ContentTree): Map<string, string> {
  const files = new Map<string, string>();
  const banner = "<!-- Generated by `pnpm coverage` from the bank file and content/. Do not edit by hand. -->\n\n";
  const { totals } = result;

  let summary = `${banner}# Question coverage\n\n`;
  summary += `| Measure | Count | % |\n| --- | --- | --- |\n`;
  summary += `| Questions in the bank | ${totals.questions} | |\n`;
  summary += `| Mapped to a lesson | ${totals.questions} | 100% |\n`;
  summary += `| Taught on ≥ 1 card | ${totals.taught} | ${pct(totals.taught, totals.questions)} |\n`;
  summary += `| 3 Why not? notes | ${totals.whyNotComplete} | ${pct(totals.whyNotComplete, totals.questions)} |\n`;
  summary += `| Lessons authored | ${totals.authoredLessons} / ${totals.lessons} | ${pct(totals.authoredLessons, totals.lessons)} |\n\n`;
  summary += `Every question maps to exactly one lesson by its ID (B-005-004-001 → lesson 5.04).\n\n`;
  summary += `| Section | Lessons | Questions | Taught | Why not? complete |\n| --- | --- | --- | --- | --- |\n`;

  for (const s of tree.sections) {
    const ls = result.lessons.filter((l) => l.id.startsWith(s.id));
    const qs = ls.flatMap((l) => l.questions);
    const taught = qs.filter((q) => q.cards.length).length;
    const wn = qs.filter((q) => q.whyNot === 3).length;
    const file = `section-${s.number}.md`;
    summary += `| [${s.number}. ${esc(s.title_en)}](${file}) | ${ls.length} | ${qs.length} | ${taught} (${pct(taught, qs.length)}) | ${wn} (${pct(wn, qs.length)}) |\n`;

    let md = `${banner}# Section ${s.number}: ${s.title_en}\n\n`;
    md += `${ls.length} lessons · ${qs.length} questions · recommended order ${s.recommended_order}\n\n`;
    for (const l of ls) {
      md += `## ${l.code} ${l.title ?? "(untitled)"}\n\n`;
      md += `Lab: ${l.labId ?? "none"}\n\nStatus: ${l.authored ? "authored" : "not yet authored"}\n\n`;
      md += `| Question | Stem | Cards | Why not? | Calc |\n| --- | --- | --- | --- | --- |\n`;
      for (const q of l.questions) {
        const cards = q.cards.length ? q.cards.map((c) => c.split("/")[1]).join(", ") : "—";
        const calc = q.calc === "verified" ? "✓ ham-sim" : q.calc === "failed" ? "✗" : "";
        md += `| ${q.id} | ${esc(q.stemEn)} | ${cards} | ${q.whyNot}/3 | ${calc} |\n`;
      }
      md += "\n";
    }
    files.set(file, md);
  }
  files.set("README.md", summary);
  return files;
}

export interface CoverageLesson {
  code: string;
  title: string;
  labId: string | null;
}

/**
 * Read lessons back out of a docs/coverage/section-N.md file: each "## x.yy Title" heading and
 * the "Lab: LAB-xx" (or "Lab: none") line under it. The database seed uses this, so the coverage
 * docs are the single list of lessons, titles and labs.
 */
export function parseCoverageLessons(md: string): CoverageLesson[] {
  const out: CoverageLesson[] = [];
  let current: CoverageLesson | null = null;
  for (const line of md.split(/\r?\n/)) {
    const h = /^##\s+(\d\.\d{2})\s+(.+?)\s*$/.exec(line);
    if (h) {
      current = { code: h[1]!, title: h[2]!, labId: null };
      out.push(current);
      continue;
    }
    const lab = /^Lab:\s*(LAB-\d{2}|none)\s*$/i.exec(line);
    if (lab && current) current.labId = lab[1]!.toLowerCase() === "none" ? null : lab[1]!.toUpperCase();
  }
  return out;
}
